// get the policy id of "request-rdf-service-file" and save it as an environment variable
if(pm.response.code < 300 && pm.response.code >= 200){
    if(pm.response.json()){
        const response = pm.response.json();
        const catalogs = Array.isArray(response) ? response : [ response ];
        const datasets = catalogs.flatMap(catalog => Array.isArray(catalog["dcat:dataset"]) ? catalog["dcat:dataset"] : [ catalog["dcat:dataset"] ]);
        console.log(JSON.stringify(datasets, undefined, 2));
        const dataset = datasets.find(asset => asset["@id"]=="request-rdf-service-file")
        pm.collectionVariables.set("POLICY_ID_RDF", dataset["odrl:hasPolicy"]["@id"]);
    }
}

pm.test("Status code is >=200 and <300", function () {
    pm.expect(pm.response.code < 300 && pm.response.code >= 200).to.be.true
});
pm.test("Policy id for asset request-rdf-service-file is set", function(){
    pm.expect(pm.collectionVariables.get("POLICY_ID_RDF")).not.to.be.undefined
})

if(!pm.collectionVariables.has("CONTRACT_AGREEMENT_ID_RDF")){
    throw new Error('Contract Agreement ID is not yet available, please execute requests "Initiate Negotiation and Get Contract Negotiation" first!');
}

pm.test("Status code is >=200 and <300", function () {
    pm.expect(pm.response.code < 300 && pm.response.code >= 200).to.be.true
});

// get the policy id of "asset-1" and save it as an environment variable
if(pm.response.code < 300 && pm.response.code >= 200){
    if(pm.response.json().length > 0){
        const rdf = pm.response.json()[0]["dcat:catalog"][0]["dcat:dataset"]
        //const rdf = dcat_datasets.find((asset) => asset["@id"] == "request-rdf-service-sparql")
        pm.collectionVariables.set("POLICY_ID_RDF", rdf["odrl:hasPolicy"]["@id"]);
    }
}

pm.test("Status code is >=200 and <300", function () {
    pm.expect(pm.response.code < 300 && pm.response.code >= 200).to.be.true
});
pm.test("Policy id for request-rdf-service-sparql is set", function(){
    pm.expect(pm.collectionVariables.get("POLICY_ID_RDF")).not.to.be.undefined
})

// get the policy id of "request-rdf-service-file" and save it as an environment variable
if(pm.response.code < 300 && pm.response.code >= 200){
    if(pm.response.json()){
        const response = pm.response.json();
        const catalogs = Array.isArray(response) ? response : [ response ];
        const datasets = catalogs.flatMap(catalog => Array.isArray(catalog["dcat:dataset"]) ? catalog["dcat:dataset"] : [ catalog["dcat:dataset"] ]);
        console.log(JSON.stringify(datasets, undefined, 2));
        const dataset = datasets.find(asset => asset["@id"]=="request-rdf-service-file")
        pm.collectionVariables.set("POLICY_ID_RDF", dataset["odrl:hasPolicy"]["@id"]);
    }
}

pm.test("Status code is >=200 and <300", function () {
    pm.expect(pm.response.code < 300 && pm.response.code >= 200).to.be.true
});
pm.test("Policy id for asset request-rdf-service-file is set", function(){
    pm.expect(pm.collectionVariables.get("POLICY_ID_RDF")).not.to.be.undefined
